package org.sleepwell.app;

import android.app.*;
import android.content.Context;
import android.os.Bundle;
import android.widget.*;
import org.json.JSONObject;
import java.util.*;
import java.util.concurrent.*;

/** Supporting measured-signal view; manual entries never receive fabricated plots. */
public final class RecordSignalsActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private RecordEntry record;private List<JSONObject> epochs=List.of(),events=List.of();private boolean original;private int generation,savedClips;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);original=state!=null&&state.getBoolean("original");load();}
    private void load(){long id=getIntent().getLongExtra("record",0);int request=++generation;Records.Factory factory=Records.factory;Context application=getApplicationContext();LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Recorded signals",this::finish);Design.text(body,"Loading signals…",15,400,Design.MUTED);
        worker.execute(()->{try(Store store=factory.open(application)){RecordEntry entry=Records.get(store,id);List<JSONObject> data=store.rows("SELECT * FROM epochs WHERE session=? ORDER BY time",""+id),analysis=store.rows("SELECT time,duration_ms FROM sound_events WHERE session=? ORDER BY time",""+id);int available=ReportSounds.read(application,store,entry).availableClips;runOnUiThread(()->{if(isDestroyed()||isFinishing()||request!=generation)return;record=entry;epochs=data;events=analysis;savedClips=available;render();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||isFinishing()||request!=generation)return;LinearLayout page=Design.page(this,false,null,n->{});RecordUi.header(page,"Recorded signals",this::finish);Design.space(page,24);Design.text(page,"Signals unavailable",22,600,Design.INK);Design.text(page,"This recording could not be opened.",15,400,Design.MUTED);Design.space(page,16);Design.button(page,"Try again",true,this::load);});}});
    }
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Recorded signals",this::finish);Design.space(body,8);Design.text(body,record.provenance(),13,500,Design.MUTED);if(record.manual()){Design.space(body,32);Design.text(body,"No sensor measurements",22,600,Design.INK);Design.space(body,10);Design.text(body,"This period was entered manually. It has no movement, microphone or light measurements.",15,400,Design.MUTED);return;}
        if(record.edited){Design.space(body,12);RecordUi.segments(body,new String[]{"Edited period","Original capture"},original?1:0,index->{original=index==1;render();});}
        long start=original?record.rawStart:record.edit.start,end=original?record.rawEnd:record.edit.end;List<JSONObject> visible=Records.window(epochs,start,end);Design.space(body,12);TextView period=Design.text(body,(record.sonar()?RecordUi.preciseClock(this,start,record.zone()):RecordUi.clock(this,start,record.zone()))+" – "+(record.sonar()?RecordUi.preciseClock(this,end,record.zone()):RecordUi.clock(this,end,record.zone())),16,600,Design.INK);period.setContentDescription("Recorded interval "+start+" to "+end+" in "+record.zone);Design.space(body,8);Design.text(body,record.sonar()?"Saved intervals · up to 5 seconds":"Saved minute averages · missing intervals stay blank",12,400,Design.MUTED);
        String[] names={record.sonar()?"Relative echo change":"Phone movement","Room noise","Room light"},metrics={"movement","noise","light"};boolean noise=false,light=false;for(int n=0;n<3;n++){boolean measured=measured(visible,metrics[n]);if(n==1)noise=measured;if(n==2)light=measured;if(!measured&&!(n==0&&record.sonar()))continue;RecordUi.heading(body,names[n]);body.addView(new RecordChart(this,visible,metrics[n],start,end,false,record.zone()).measurement(names[n]),new LinearLayout.LayoutParams(-1,Design.dp(this,160)));if(n==1)Design.text(body,"Relative sound level · not calibrated decibels.",11,400,Design.MUTED);}
        if(record.sonar()){quality(body,visible,start,end);PlanActivity.detail(body,"wave","Breathing rhythm","Recorded periodic echoes",null,()->startActivity(RecordUi.intent(this,EchoPeriodsActivity.class).putExtra("record",record.id)));}else if(!measured(visible,"movement"))Design.text(body,"No phone movement measurements in this period.",14,400,Design.MUTED);
        if(!noise&&!light){Design.space(body,16);Design.text(body,savedClips>0?"No sound-level or light readings saved.":"No sound-level, light readings or audio clips saved.",12,400,Design.MUTED);}
        boolean analysis=false;for(JSONObject event:events){long time=event.optLong("time"),duration=Math.max(0,event.optLong("duration_ms"));if(time<end&&time+duration>start){analysis=true;break;}}SoundAnalysisCopy.Info sound=SoundAnalysisCopy.of(record);RecordUi.heading(body,"Sound analysis");Design.text(body,sound.title,14,500,sound.attention?Design.BROWN:Design.MUTED);if(!sound.detail.isEmpty())Design.text(body,(record.edited?"Original recording · ":"")+sound.detail,12,400,Design.MUTED);if(analysis||!record.soundAnalysis.isEmpty())PlanActivity.detail(body,"wave","Sound events","Estimates and recordings",null,()->startActivity(RecordUi.intent(this,SoundEventsActivity.class).putExtra("record",record.id)));
        if(!record.sonar()&&record.source.equals("tracked"))PlanActivity.detail(body,"link","Paired movement","Separate peer readings and quality",null,()->startActivity(RecordUi.intent(this,PairMotionSavedActivity.class).putExtra("record",record.id)));
        PlanActivity.detail(body,"moon","Timed dream cues","Saved requests for this night",null,()->startActivity(RecordUi.intent(this,DreamCueHistoryActivity.class).putExtra("record",record.id)));
        if(savedClips>0)Design.item(body,"sound","Review sound recordings",savedClips+" saved",()->startActivity(RecordUi.intent(this,SoundEventsActivity.class).putExtra("record",record.id)));else if(noise||light){Design.space(body,8);Design.text(body,"No audio clips saved.",12,400,Design.MUTED);}if(!record.edit.note.isBlank()){RecordUi.heading(body,"Notes");Design.text(body,record.edit.note,14,400,Design.INK);}if(!record.edit.tags.isEmpty()){RecordUi.heading(body,"Tags");Design.text(body,record.edit.tags.stream().map(tag->TagCodec.display(record.edit,tag)).collect(java.util.stream.Collectors.joining(" · ")),14,400,Design.MUTED);PlanActivity.detail(body,"tag","Compare & manage tags","Saved record associations",null,()->startActivity(RecordUi.intent(this,TagManagementActivity.class).putExtra("tag",record.edit.tags.get(0))));}PlanActivity.detail(body,"memory","Dream diary","Private journal entries",null,()->startActivity(RecordUi.intent(this,DiaryActivity.class)));Design.space(body,16);
    }
    private static boolean measured(List<JSONObject> rows,String key){for(JSONObject row:rows){if(row.isNull(key))continue;double value=row.optDouble(key,Double.NaN);if(Double.isFinite(value)&&value>=0)return true;}return false;}
    private void quality(LinearLayout body,List<JSONObject> visible,long start,long end){
        RecordUi.heading(body,"Signal quality");Map<String,Long> totals=new LinkedHashMap<>();long coveredUntil=start,missing=0;for(JSONObject row:visible){long from=Math.max(start,row.optLong("start")),to=Math.min(end,row.optLong("time"));if(to<=from)continue;if(from>coveredUntil)missing+=from-coveredUntil;long uniqueFrom=Math.max(from,coveredUntil);if(to>uniqueFrom){String state=row.optString("signal_quality","UNAVAILABLE");totals.merge(state,to-uniqueFrom,Long::sum);coveredUntil=to;}}if(coveredUntil<end)missing+=end-coveredUntil;
        for(Map.Entry<String,Long> entry:totals.entrySet())qualityRow(body,qualityName(entry.getKey()),entry.getValue());if(missing>0)qualityRow(body,"Not recorded",missing);if(totals.isEmpty()&&missing==0)Design.text(body,"No quality intervals saved.",14,400,Design.MUTED);Design.space(body,8);Design.text(body,"Unavailable intervals stay blank. Zero is a measured value.",12,400,Design.MUTED);
    }
    private void qualityRow(LinearLayout body,String state,long duration){LinearLayout row=Design.row(this);Design.pad(row,0,7);row.addView(Design.text(this,state,14,500,Design.INK),new LinearLayout.LayoutParams(0,-2,1));row.addView(Design.text(this,RecordUi.duration(duration),14,400,Design.MUTED));row.setContentDescription(state+" · "+RecordUi.duration(duration));body.addView(row,new LinearLayout.LayoutParams(-1,-2));}
    private static String qualityName(String state){return switch(state){case "VALID"->"Measured";case "CALIBRATING"->"Calibrating";case "NEEDS_MOVEMENT"->"Awaiting movement";case "NO_ECHO"->"No echo";case "CLIPPED"->"Signal clipped";case "TIMING_LOST"->"Timing lost";case "ROUTE_LOST"->"Audio route lost";case "SILENCED"->"Input silenced";case "CHARGING_LOST"->"Charging stopped";case "CUE_ACTIVE"->"Vibration cue settling";default->"Unavailable";};}
    @Override protected void onSaveInstanceState(Bundle state){state.putBoolean("original",original);super.onSaveInstanceState(state);}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    void awaitReaders(long timeoutMillis)throws Exception{if(worker.isShutdown()){if(!worker.awaitTermination(timeoutMillis,TimeUnit.MILLISECONDS))throw new TimeoutException("Signal reader still active");}else worker.submit(()->{}).get(timeoutMillis,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
}
